# ================================================================== clase 2
L(OA14, 2,
  "Este cuaderno y un lápiz.",
  "Aprenderé a usar conectores adecuados (de tiempo, de causa, de consecuencia y de contraste) para unir las ideas y hechos de una narración.",
  ["Reconozco la estructura de una narración.", "Sé escribir oraciones completas."],
  ["Los conectores son palabras o expresiones que unen oraciones y muestran la relación entre ellas. En una narración usamos varios tipos. Los conectores de tiempo ordenan los hechos: primero, luego, después, de pronto, mientras tanto, al final. Los de causa explican por qué ocurre algo: porque, ya que, debido a. Los de consecuencia muestran el resultado: por eso, así que, entonces. Los de contraste oponen dos ideas: pero, sin embargo, aunque.",
   "Elegir bien el conector cambia el sentido. «Llovía, por eso salimos con paraguas» muestra una consecuencia. «Llovía, pero salimos sin paraguas» muestra un contraste. Si uso siempre «y entonces» o «después», la narración se vuelve monótona. Variar los conectores hace el texto más fluido y más claro.",
   "Para revisar mis conectores leo cada unión y me pregunto: ¿qué relación hay entre estas dos ideas?, ¿tiempo, causa, consecuencia o contraste? Luego escojo el conector que la expresa. Los conectores de tiempo se separan con coma cuando abren una oración: «De pronto, se apagó la luz». Evito repetir el mismo conector tres veces seguidas."],
  [("conector", "palabra que une ideas y muestra su relación"), ("causa", "motivo por el que ocurre algo"), ("consecuencia", "resultado de algo"), ("contraste", "oposición entre dos ideas"), ("monótono", "que siempre es igual")],
  [("Elegir el conector de contraste", "Completa: «Quería ir al parque, ___ estaba cerrado». ¿Eliges «por eso» o «pero»?",
    ["La segunda idea se opone a la primera.", "El conector de contraste es «pero»."], "Pero"),
   ("Elegir el conector de consecuencia", "Completa: «Se cortó la luz, ___ encendimos las velas». ¿Eliges «porque» o «así que»?",
    ["Encender las velas es el resultado.", "Una consecuencia se une con «así que»."], "Así que")],
  [("Repetir «y entonces» en todas las oraciones.", "El texto se vuelve monótono.", "Varía con conectores de tiempo, causa y contraste."),
   ("Usar «porque» donde corresponde una consecuencia.", "Cambia el sentido de la relación.", "Pregunta si la idea es causa o resultado.")],
  ([E("«Primero», «luego» y «después» ordenan hechos en el tiempo. ¿Son conectores de tiempo o de contraste?", "De tiempo", "Ordenan los hechos."),
    E("«Pero» y «sin embargo» oponen ideas. ¿Son conectores de contraste o de causa?", "De contraste", "Oponen dos ideas."),
    E("«Porque» explica el motivo de algo. ¿Es un conector de causa o de consecuencia?", "De causa", "Introduce la razón.")],
   [E("Completa con un conector de tiempo: «___, se apagó la luz en toda la calle». ¿Eliges «De pronto» o «Aunque»?", "De pronto", "Marca un momento inesperado en el tiempo."),
    E("Completa: «Estudió mucho, ___ obtuvo una buena nota». ¿Eliges «por eso» o «pero»?", "Por eso", "La buena nota es consecuencia de estudiar."),
    E("Completa: «Se quedó en casa ___ tenía fiebre». ¿Eliges «porque» o «por eso»?", "Porque", "La fiebre es la causa de quedarse.")],
   [E("Completa: «Corrió con todas sus fuerzas, ___ no alcanzó el bus». ¿Eliges «sin embargo» o «porque»?", "Sin embargo", "Opone el esfuerzo al resultado."),
    E("Ordena los hechos con conectores: a) «Luego se puso las botas.» b) «Primero abrió el paraguas.» c) «Al final, salió a la calle.» Escribe las letras en orden.", "b, a, c", "Primero, luego y al final ordenan los hechos."),
    arith("Una narración tiene 12 oraciones. En 5 usa conectores. ¿En cuántas no usa conectores?", "12-5", "Se restan las oraciones con conectores del total.", " oraciones")],
   [E("Un compañero escribe: «Fue al mercado y entonces compró pan y entonces volvió y entonces comió». ¿Qué problema tiene su texto?", "Repite el mismo conector", "Usa «entonces» tres veces seguidas."),
    E("En «Era temprano, pero ya hacía calor», ¿«pero» expresa una oposición? Responde sí o no.", "Sí", "Se opone lo temprano al calor.")],
   [E("Une con un conector de contraste: «Tenía miedo. Cruzó el puente». ¿Cuál queda mejor: «Tenía miedo, pero cruzó el puente» o «Tenía miedo, por eso cruzó el puente»?", "Tenía miedo, pero cruzó el puente", "La segunda parte se opone al miedo."),
    E("Dos versiones: A) «Llovió mucho porque las calles se inundaron». B) «Llovió mucho, así que las calles se inundaron». ¿Cuál expresa bien la relación?", "B", "Las calles se inundaron como consecuencia de la lluvia.")]),
  [E("Estás contando a tu curso por qué llegaste tarde. Empiezas: «Se me perdió una zapatilla, ___ tuve que buscarla». ¿Eliges «por eso» o «pero»?", "Por eso", "Buscarla es la consecuencia de perderla.")],
  [E("Nombra un conector de tiempo.", "Primero, luego, después, de pronto, mientras tanto o al final", "Son conectores de tiempo."),
   E("¿Qué conector sirve para oponer ideas?", "Pero o sin embargo", "Ambos expresan contraste."),
   E("¿Qué conector expresa una consecuencia?", "Por eso o así que", "Muestran el resultado.")],
  ("Escribe un párrafo de cinco oraciones que cuente cómo preparaste una colación para el recreo. Debes usar al menos un conector de tiempo, uno de causa, uno de consecuencia y uno de contraste. Subraya los conectores y escribe al lado qué tipo es cada uno.",
   "Primero busqué pan en la cocina. Estaba duro, así que lo tosté. Quería queso, pero no había. Luego usé palta, porque era lo que quedaba. Al final, guardé todo en mi mochila.",
   ["cuatro tipos de conector", "subrayados e identificados", "relación entre ideas clara"], ["el párrafo con los conectores subrayados"],
   ["repetir el mismo conector", "usar uno que cambia el sentido"], "Pide a alguien que busque tus conectores y diga qué tipo son."),
  "Escribe una oración con «sin embargo» sobre tu día.",
  "Cuenta algo que te pasó hoy usando «primero», «luego» y «al final».")

